findings.codeql_raw_query:
/**
 * @name User-controlled setattr attribute name
 * @description Using setattr with a user-controlled attribute name can lead to object modification
 * @kind path-problem
 * @problem.severity warning
 * @id py/user-controlled-setattr
 * @tags security
 *       external/cwe/cwe-915
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module SetattrConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Parameters of methods in PluginManager class
    exists(Function f, Class c |
      f.getScope() = c and
      c.getName() = "PluginManager" and
      source instanceof DataFlow::ParameterNode and
      source.getScope() = f
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::builtin("setattr").getACall() and
      sink = call.getArg(1) // The attribute name argument
    )
  }
}

module SetattrFlow = TaintTracking::Global<SetattrConfig>;
import SetattrFlow::PathGraph

from SetattrFlow::PathNode source, SetattrFlow::PathNode sink
where SetattrFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Attribute name in setattr comes from $@.", source.getNode(), "parameter"
